"""Render the committed exact witnesses without invoking a solver."""
from pathlib import Path
from parity_ot.certificates import exact_model, load_certificates, verify_certificate

lines = ["# Exact rational certificate tables", "",
         "Generated by `python scripts/render_certificates.py`. All data are synthetic.",
         "Primal columns give joint masses, not conditional probabilities. Dual columns",
         "give coefficients on the named equality rows; omitted coefficients are zero.",
         "Every state and equality is checked with exact Fraction arithmetic.", ""]
for name, certificate in load_certificates().items():
    verify_certificate(name, certificate)
    states, labels, rows, prices, payoff = exact_model(name)
    lines += [f"## {name}: [{certificate['lower']['value']}, {certificate['upper']['value']}]", "",
              "| State | Target | Lower primal | Upper primal |",
              "| --- | --- | --- | --- |"]
    for i, state in enumerate(states):
        lines.append(f"| {state} | {payoff[i]} | {certificate['lower']['primal'][i]} | {certificate['upper']['primal'][i]} |")
    lines += ["", "| Equality row | Price | Lower dual | Upper dual |", "| --- | --- | --- | --- |"]
    for j, label in enumerate(labels):
        lines.append(f"| {label} | {prices[j]} | {certificate['lower']['dual'][j]} | {certificate['upper']['dual'][j]} |")
    lines.append("")
path = Path(__file__).resolve().parents[1] / "research/rational_certificates.md"
path.write_text("\n".join(lines), encoding="utf-8")
print(f"Wrote {path}")
